// Apparent geocentric positions against NASA/JPL Horizons.
//
// Fixtures: test/fixtures/horizons/*.csv.gz, regenerated by
// tool/horizons/fetch.py (one request per series; exact query parameters in
// test/fixtures/horizons/queries.json). Horizons quantity 31: apparent
// ecliptic longitude and latitude of date; quantity 20: range (AU). Observer:
// geocentre, UT times (Horizons applies its own Delta T; this package uses its
// USNO/IERS table).
//
// Tolerances are the measured maxima plus a small margin; the measured values
// are in README.md.
// ignore_for_file: avoid_print

import 'dart:io';
import 'dart:convert';
import 'dart:math' as math;

import 'package:test/test.dart';
import 'package:astro_ephemeris/astro_ephemeris.dart';

const String _dir = 'test/fixtures/horizons';
const double _jd2025 = 2460676.5; // 2025-01-01
const double _jd2050 = 2469807.5; // 2050-01-01

class _Row {
  _Row(this.jd, this.lon, this.lat, this.range);
  final double jd, lon, lat, range;
}

List<_Row> _load(String name) {
  final List<String> lines = const LineSplitter().convert(
    utf8.decode(gzip.decode(File('$_dir/$name.csv.gz').readAsBytesSync())),
  );
  return <_Row>[
    for (final String l in lines.skip(1).where((String l) => l.isNotEmpty))
      () {
        final List<double> f = l.split(',').map(double.parse).toList();
        return _Row(f[0], f[1], f[2], f[3]);
      }(),
  ];
}

double _angleDiff(double a, double b) {
  double d = (a - b) % 360.0;
  if (d > 180.0) d -= 360.0;
  return d;
}

class _Stat {
  final List<double> _v = <double>[];
  void add(double x) => _v.add(x.abs());
  double get max => _v.isEmpty ? 0 : _v.reduce(math.max);
  double get p95 {
    if (_v.isEmpty) return 0;
    final List<double> s = List<double>.of(_v)..sort();
    return s[((s.length - 1) * 0.95).round()];
  }
}

class _Tol {
  const _Tol(this.lonPast, this.lon2025, this.lon2050, this.lat, this.distRel);

  /// Max longitude error (arcsec) 1900-2025, 2025-2050 and 2050-2100.
  final double lonPast, lon2025, lon2050;

  /// Max latitude error, arcsec.
  final double lat;

  /// Max relative distance error.
  final double distRel;
}

// Measured max + margin (see README.md).
const Map<String, (Body, _Tol)> _series = <String, (Body, _Tol)>{
  'sun': (Body.sun, _Tol(2.5, 2.3, 3.1, 2.1, 1.6e-5)),
  'mercury': (Body.mercury, _Tol(13.5, 9.7, 13.5, 9.5, 5.5e-5)),
  'venus': (Body.venus, _Tol(21, 18.5, 16.5, 13.2, 6.8e-5)),
  'mars': (Body.mars, _Tol(11.7, 13.9, 14, 17, 9.3e-5)),
  'jupiter': (Body.jupiter, _Tol(11.2, 6.9, 10.7, 15.2, 8.3e-5)),
  'saturn': (Body.saturn, _Tol(14.3, 11.7, 10.4, 24, 7.9e-5)),
  'uranus': (Body.uranus, _Tol(13.3, 8.3, 5.3, 21, 5.2e-5)),
  'neptune': (Body.neptune, _Tol(20.5, 13.5, 21, 11, 5.2e-5)),
  'pluto': (Body.pluto, _Tol(4.2, 5.6, 9.4, 1.7, 3.9e-5)),
  'chiron': (Body.chiron, _Tol(0.55, 0.41, 0.51, 0.24, 2.0e-6)),
  'moon_long': (Body.moon, _Tol(5.0, 4.8, 19.5, 3.2, 1.5e-4)),
};

void main() {
  group('vs Horizons, 1900-2100', () {
    _series.forEach((String name, (Body, _Tol) spec) {
      final Body body = spec.$1;
      final _Tol tol = spec.$2;
      test('${body.name} ($name.csv.gz)', () {
        final List<_Row> rows = _load(name);
        final _Stat lonPast = _Stat(), lon2025 = _Stat(), lon2050 = _Stat();
        final _Stat lat = _Stat(), dist = _Stat();
        for (final _Row r in rows) {
          final BodyPosition p = position(body, r.jd);
          expect(p.longitude, inInclusiveRange(0, 360));
          (r.jd < _jd2025
                  ? lonPast
                  : r.jd < _jd2050
                      ? lon2025
                      : lon2050)
              .add(_angleDiff(p.longitude, r.lon) * 3600);
          lat.add((p.latitude - r.lat) * 3600);
          dist.add((p.distance - r.range) / r.range);
        }
        print(
          'MEASURED ${body.name.padRight(8)} n=${rows.length} '
          'lon<2025 max ${lonPast.max.toStringAsFixed(2)}" '
          'p95 ${lonPast.p95.toStringAsFixed(2)}" | '
          '2025-2050 max ${lon2025.max.toStringAsFixed(2)}" | '
          '2050-2100 max ${lon2050.max.toStringAsFixed(2)}" | '
          'lat max ${lat.max.toStringAsFixed(2)}" | '
          'dist rel max ${dist.max.toStringAsExponential(2)}',
        );
        expect(lonPast.max, lessThan(tol.lonPast), reason: 'lon <2025');
        expect(lon2025.max, lessThan(tol.lon2025), reason: 'lon 2025-2050');
        expect(lon2050.max, lessThan(tol.lon2050), reason: 'lon 2050-2100');
        expect(lat.max, lessThan(tol.lat), reason: 'lat');
        expect(dist.max, lessThan(tol.distRel), reason: 'distance');
      });
    });
  });

  test('Moon every 6 hours, 2024-2025 (moon_fine.csv.gz)', () {
    final List<_Row> rows = _load('moon_fine');
    final _Stat lon = _Stat(), lat = _Stat();
    for (final _Row r in rows) {
      final BodyPosition p = position(Body.moon, r.jd);
      lon.add(_angleDiff(p.longitude, r.lon) * 3600);
      lat.add((p.latitude - r.lat) * 3600);
    }
    print(
      'MEASURED moon_fine n=${rows.length} lon max ${lon.max.toStringAsFixed(2)}" '
      'p95 ${lon.p95.toStringAsFixed(2)}" lat max ${lat.max.toStringAsFixed(2)}"',
    );
    expect(lon.max, lessThan(4.8));
    expect(lat.max, lessThan(1.2));
  });

  test('Moon speed vs central difference of Horizons longitudes', () {
    final List<_Row> rows = _load('moon_fine');
    final _Stat spd = _Stat();
    for (int i = 1; i < rows.length - 1; i++) {
      final double dt = rows[i + 1].jd - rows[i - 1].jd;
      final double ref = _angleDiff(rows[i + 1].lon, rows[i - 1].lon) / dt;
      spd.add((position(Body.moon, rows[i].jd).speedLongitude - ref) * 3600);
    }
    print('MEASURED moon speed max ${spd.max.toStringAsFixed(2)}"/day '
        'p95 ${spd.p95.toStringAsFixed(2)}"/day');
    expect(spd.max, lessThan(8));
  });

  test('eclipticLongitude equals position().longitude', () {
    for (final _Row r in _load('mars').take(50)) {
      expect(eclipticLongitude(Body.mars, r.jd),
          position(Body.mars, r.jd).longitude);
    }
  });
}
